# owner: platform
"""Absence notices for parents, built from marks."""

from typing import List
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed


def check_marks(
    student: Student, marks: List[Mark]
) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError("mark is for another student")


def absent_days(
    student: Student, marks: List[Mark]
) -> List[date]:
    check_marks(student, marks)
    missed = days_missed(marks)
    if not missed:
        raise ValueError("no absences to write about")
    return missed


def absence_notice(
    student: Student, marks: List[Mark]
) -> str:
    missed = absent_days(student, marks)
    dates = ", ".join(item.isoformat() for item in missed)
    unit = "day" if len(missed) == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {len(missed)} {unit}: {dates}."
